"""Explain nesting, early parameter checks and metadata continuity."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1793': ('잠깐 조용히 해 달라는 요청이 두 개 겹쳤다면 하나만 취소해도 아직 요청 하나가 남아요. 중첩된 검사 중단도 숫자로 남은 요청을 세어요.', '현재 작업의 보고 중단 횟수와 runtime 상태를 구별합니다.', '0에서 시작해 disable, disable, enable, enable 뒤의 숫자 1, 2, 1, 0을 적으세요.', ['current는 현재 실행 중인 작업을 가리켜요. kmsan_disable_current는 그 작업의 kmsan_ctx.depth를 하나 늘려요. depth는 중첩된 보고 중단 요청이 얼마나 남았는지 관리하는 숫자예요.', 'kmsan_enable_current는 짝이 되는 중단을 하나 풀기 위해 depth를 하나 줄여요. 여러 함수가 각자 중단을 요청할 수 있으므로 켜짐·꺼짐 두 값만으로는 남은 중단 요청을 구분하기 어려워요.', '처음 0에서 disable을 두 번 하면 1, 2가 돼요. enable 한 번 뒤에는 1이므로 아직 중단 요청이 하나 남고, 두 번째 enable 뒤 0으로 돌아와요. enable을 한 번 불렀다고 모든 중단이 없어지는 것이 아니에요.', '원문의 enable은 depth가 0이면 경고한 뒤, 실행이 계속될 경우 감소해요. 자동으로 0에 고정하는 코드가 아니에요. disable 없는 enable은 정상 사용 조건을 어긴 것이므로 짝을 맞추는 예제로 연습하세요.', 'disable은 증가한 뒤 0인지 경고해요. depth는 unsigned int이므로 너무 많이 증가해 수의 범위를 넘어가는 경우도 정상으로 취급하지 않아요. 이런 한계까지 고려하면 무한히 중첩해도 괜찮다는 뜻이 아님을 알 수 있어요.', '이 depth는 같은 구조체의 kmsan_in_runtime과 별도 필드예요. 원인 사슬 번호에 들어 있는 깊이도 또 다른 정보예요. 문서는 중단 구간을 짧게 하고 조기 반환이 있어도 disable과 enable의 짝을 지키도록 읽게 해요.'], [('현재 작업의 depth와 도구 자신의 처리 상태 kmsan_in_runtime은 같은 변수인가요?', ['네. 하나의 켜짐·꺼짐 값을 두 이름으로 불러요', '아니요. 구조체 안의 별도 필드예요'], '정답은 두 번째예요. depth는 unsigned int, kmsan_in_runtime은 int로 따로 선언돼요. 비슷한 중첩 개념이 있어도 어느 상태를 세는지 구분해야 해요.'), ('먼저 disable하지 않고 enable만 호출해도 정상인가요?', ['아니요. 앞선 disable과 짝을 맞춰야 해요', '네. 숫자를 자동으로 0에 고정해 줘요'], '정답은 첫 번째예요. 원문은 0에서 경고하고 감소를 수행하는 흐름이에요. 잘못된 호출을 자동으로 정상화하는 함수가 아니에요.')]), 'os1794': ('입구에서 미리 검사하면 문제를 빨리 찾을 수 있어요. 하지만 모든 물건을 빠짐없이 검사하는 입구가 아니라면 뒤로 전달할 검사표도 필요해요.', '인자·반환값의 이른 검사와 상태 전달 공간의 필요성을 이해합니다.', '함수 입구의 빠른 검사와 함수 사이 검사표 전달을 두 줄로 그리고 서로 다른 역할을 적으세요.', ['함수 인자는 함수를 부를 때 넘기는 값이고 반환값은 함수가 돌려주는 값이에요. 준비되지 않은 값을 멀리 전달한 뒤 발견하면 원인을 찾기 어려울 수 있어요. 전달 시점 가까이에서 검사하면 문제를 일찍 알 수 있어요.', 'CONFIG_KMSAN_CHECK_PARAM_RETVAL은 이런 인자·반환값 검사를 위한 설정이에요. 고정 문서는 기본으로 켜져 있다고 설명해요. 목적은 미준비 값 사용을 더 일찍 보고하는 것이며 실제 값을 전부 0으로 바꾸는 기능이 아니에요.', '하지만 기본으로 켜졌다는 말이 모든 인자를 반드시 검사한다는 뜻은 아니에요. 문서는 LLVM의 구현상 noundef 표식이 붙은 인자에만 해당 검사가 적용된다고 설명해요. LLVM은 컴파일 과정에 쓰이는 도구 모음이에요.', 'noundef는 컴파일러의 중간 표현에서 값의 정의 여부에 관한 조건을 나타내는 표식이에요. 여기서는 이름을 외우기보다 검사 대상이 이 표식에 따라 제한된다는 점을 먼저 기억하세요. 설정 하나만 보고 모든 경로를 검사했다고 결론 내리지 마세요.', '그래서 kmsan_context_state라는 검사 상태 공간이 계속 필요해요. 이 공간은 인자와 반환값의 shadow·origin을 전달하는 데 쓰여요. 빠른 검사가 모든 값을 다루지 못하므로 상태 정보를 뒤로 전달하는 길도 유지해야 해요.', '빠른 검사는 언제 문제를 알릴지와 관련되고, 상태 전달은 다음 계산이 무엇을 알고 있어야 하는지와 관련돼요. 둘을 하나의 기능으로 생각하면 상태 공간을 없애도 된다고 오해하기 쉬워요. 이 수업은 고정 문서의 설명이며 실제 컴파일러 계측을 실행한 검증은 아니에요.'], [('PARAM_RETVAL을 켰다는 이유만으로 cstate 검사 정보 공간을 없애도 되나요?', ['네. 모든 인자가 빠짐없이 검사된 것이니까요', '아니요. 모든 인자가 검사된다는 보장이 없어요'], '정답은 두 번째예요. 문서는 noundef 표식의 제한 때문에 검사 상태 저장 공간을 포기할 수 없다고 설명해요. 기본 활성과 모든 경로 검증은 다른 뜻이에요.'), ('이 설정의 주된 목적은 무엇인가요?', ['인자·반환값의 미준비 사용을 더 일찍 알리는 것이에요', '모든 실제 인자 값을 0으로 고치는 것이에요'], '정답은 첫 번째예요. 검사와 보고를 추가하는 기능이에요. 프로그램의 원래 데이터를 자동으로 고쳐 주는 기능으로 해석하면 안 돼요.')]), 'os1795': ('옆집 두 곳의 서류가 서류함에서도 나란히 있다는 보장은 없어요. 실제 데이터의 이웃 관계와 검사표의 이웃 관계를 따로 봐야 해요.', '데이터 페이지와 검사 페이지의 연속성 조건을 이해합니다.', '데이터 A·B는 붙여 그리고 shadow A·B는 떨어뜨려 그리세요. A 검사표 끝에서 바로 다음으로 가면 B인지 확인해 보세요.', ['페이지는 메모리를 일정한 크기로 나눈 덩어리예요. 각 데이터 페이지에는 준비 상태표 shadow와 원인 정보표 origin 페이지가 연결돼요. 데이터 페이지 주소와 검사 페이지 주소는 서로 다른 공간에 있어요.', '연속이라는 말은 한 덩어리가 끝난 바로 다음 위치에서 다음 덩어리가 시작한다는 뜻이에요. 데이터 A와 B가 연속이어도 A의 shadow와 B의 shadow가 연속이라는 보장은 없어요. 각자 연결된 검사 페이지를 확인해야 해요.', '고정 문서는 부팅 때 검사 페이지를 마련할 무렵 이미 주소 공간이 조각나 있을 수 있다고 설명해요. 데이터 페이지와 검사 페이지가 섞여 놓일 수 있어서 가까운 데이터의 검사표가 멀리 떨어지는 경우가 생겨요. 이렇게 공간이 흩어지는 현상을 단편화라고 불러요.', '예를 들어 한 페이지가 4096바이트이고 A의 shadow 시작이 100000이라고 해 봐요. A 뒤가 곧 B의 shadow라면 B는 104096에서 시작해야 해요. 그런데 실제 B의 shadow가 200000이면 단순히 A 주소에 4096을 더해 B를 찾을 수 없어요. 숫자는 설명용 주소예요.', '문서는 같은 alloc_pages 호출로 받은 연속 페이지에는 연속 메타데이터가 있다고 설명해요. 그러나 서로 다른 할당의 페이지나 커널 데이터·CPU별 공간에는 같은 보장을 할 수 없다고 해요. alloc_pages는 페이지를 할당받는 함수예요.', '따라서 페이지 경계를 가로지르는 검사 정보 접근은 시작 포인터만 확인해서 충분하다고 볼 수 없어요. 뒤 검사 공간의 연결 관계도 맞아야 해요. 데이터가 연속이라는 사실을 모든 검사 공간의 연속성 증거로 대신하지 마세요.'], [('나란한 두 데이터 페이지의 shadow·origin도 언제나 나란한가요?', ['네. 데이터 주소와 검사표 주소의 배치는 항상 같아요', '아니요. 할당과 연결 방식에 따라 떨어질 수 있어요'], '정답은 두 번째예요. 원문 문서는 데이터와 검사 페이지가 섞이거나 따로 배치될 수 있다고 설명해요. 각각의 연결 관계를 확인해야 해요.'), ('고정 문서가 연속 메타데이터를 보장하는 대표적인 범위는 무엇인가요?', ['같은 alloc_pages 호출로 받은 연속 페이지예요', '서로 다른 할당과 모든 CPU별 데이터 공간이에요'], '정답은 첫 번째예요. 하나의 할당에서 함께 받은 페이지의 조건이에요. 다른 할당이나 모든 커널 영역까지 자동으로 넓힐 수 없어요.')]), 'os1796': ('안내문에 우회한다고 적혀 있어도 실제 길의 표지판이 어디로 이어지는지 확인해야 해요. 설명과 코드가 다르면 그 차이를 그대로 읽어요.', '비연속 경고와 대체 페이지로 이동하는 조건을 구별합니다.', '검사 켜짐 → 연속성 경고 → shadow 조회 성공 → 실제 포인터 반환의 화살표를 그리세요. 경고 뒤 계속 실행되는 경우예요.', ['고정 문서는 검사 정보가 연속하지 않은 페이지 경계를 만나면 가짜 shadow·origin 영역을 반환한다고 설명해요. 가짜 영역인 dummy는 실제 검사 정보를 얻을 수 없을 때 쓰는 대체 공간이에요. 그러나 같은 버전의 실제 함수 조건도 함께 봐야 해요.', 'shadow.c의 kmsan_get_shadow_origin_ptr는 먼저 KMSAN이 꺼졌으면 return_dummy로 가요. 켜져 있으면 검사 정보가 연속하는지 확인한 결과로 KMSAN_WARN_ON을 호출해요. 이 줄에는 실패하면 return_dummy로 간다는 goto가 없어요.', '경고 뒤 실행이 계속되는 경우 바로 다음에 shadow를 조회해요. 조회한 shadow가 NULL이면 그때 return_dummy로 가요. shadow가 있으면 실제 shadow를 담고 origin도 조회해서 반환해요.', '따라서 연속성 확인이 실패해 경고했고 shadow 조회는 성공한 경우, 경고와 실제 포인터 반환이 함께 나타날 수 있어요. 경고 설정 때문에 실행이 멈추는 경우까지 무조건 계속된다고 말하는 것은 아니에요. 여기서는 계속 실행되는 코드 경로를 읽어요.', '경고는 문제를 알리는 동작이고 goto는 실행 위치를 옮기는 동작이에요. 경고 문장만 보고 대체 공간으로 이동했다고 생각하면 제어 흐름을 잘못 읽게 돼요. 실제 return과 goto가 어느 조건에 붙어 있는지 표시하세요.', '해설에는 문서가 설명한 동작과 원문에서 확인한 분기를 구분해서 남겨야 해요. 실제 포인터가 반환됐다는 사실도 비연속 접근이 안전하다는 증명은 아니에요. 이 수업에서는 잘못된 커널 접근을 실행하지 않고 조건과 반환 경로를 비교해요.'], [('경고 뒤 실행이 계속될 때, 연속성 실패 경고만으로 바로 dummy를 반환하나요?', ['네. 그 경고 줄에 무조건 goto return_dummy가 있어요', '아니요. 이어서 shadow 조회를 하고 그 결과를 살펴요'], '정답은 두 번째예요. 원문에서 dummy로 가는 별도 조건은 비활성 또는 shadow 없음이에요. 경고와 이동 명령은 구별해야 해요.'), ('고정 문서의 설명과 실제 함수의 분기가 다르면 어떻게 설명해야 하나요?', ['각각의 내용과 확인한 차이를 구분해서 적어요', '같은 동작이라고 가정하고 차이를 지워요'], '정답은 첫 번째예요. 원문에서 관찰한 제어 흐름을 문서 문장에 맞춰 바꿔 읽으면 안 돼요. 확인한 버전과 조건을 함께 밝혀야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_444.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
